-- Talentra physical baseline v2. PostgreSQL 18. Apply to an EMPTY dedicated database.

-- Engine execution status is recorded in evidence; SQL source alone is not certification.

BEGIN;

CREATE SCHEMA IF NOT EXISTS talentra;

SET search_path = talentra, public;

CREATE TABLE "reference_domain" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(80) NOT NULL,
  "description" varchar(2000) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_reference_domain_code" UNIQUE ("code")
);

CREATE TABLE "reference_value" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "reference_domain_id" bigint NOT NULL,
  "code" varchar(80) NOT NULL,
  "label_key" varchar(80) NOT NULL,
  "active" boolean DEFAULT FALSE NOT NULL,
  "sort_order" integer NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_reference_value_reference_domain_id_code" UNIQUE ("reference_domain_id", "code"),
  CONSTRAINT "ck_reference_value_1" CHECK ("sort_order" >= 0)
);

CREATE TABLE "ui_translation" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "label_key" varchar(80) NOT NULL,
  "language_code" varchar(10) NOT NULL,
  "translated_text" varchar(2000) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_ui_translation_label_key_language_code" UNIQUE ("label_key", "language_code")
);

CREATE TABLE "country" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" char(2) NOT NULL,
  "name" varchar(150) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_country_code" UNIQUE ("code")
);

CREATE TABLE "state" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "country_id" bigint NOT NULL,
  "code" varchar(80) NOT NULL,
  "name" varchar(150) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_state_country_id_code" UNIQUE ("country_id", "code")
);

CREATE TABLE "city" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "state_id" bigint NOT NULL,
  "name" varchar(150) NOT NULL,
  "latitude" numeric(9,6),
  "longitude" numeric(9,6),
  "coordinate_source" varchar(2000),
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "ck_city_1" CHECK ("latitude" BETWEEN -90 AND 90),
  CONSTRAINT "ck_city_2" CHECK ("longitude" BETWEEN -180 AND 180)
);

CREATE TABLE "skill" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(80) NOT NULL,
  "name" varchar(150) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_skill_code" UNIQUE ("code")
);

CREATE TABLE "qualification" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(80) NOT NULL,
  "name" varchar(150) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_qualification_code" UNIQUE ("code")
);

CREATE TABLE "industry" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(80) NOT NULL,
  "name" varchar(150) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_industry_code" UNIQUE ("code")
);

CREATE TABLE "job_role" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(80) NOT NULL,
  "name" varchar(150) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_job_role_code" UNIQUE ("code")
);

CREATE TABLE "app_user" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "email" varchar(254) NOT NULL,
  "person_name" varchar(150) NOT NULL,
  "status_reference_value_id" bigint NOT NULL,
  "preferred_language" varchar(10) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_app_user_email" UNIQUE ("email"),
  CONSTRAINT "ck_app_user_1" CHECK (email = lower(email))
);

CREATE TABLE "credential" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "app_user_id" bigint NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "changed_at" timestamptz NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_credential_app_user_id" UNIQUE ("app_user_id")
);

CREATE TABLE "access_role" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(80) NOT NULL,
  "name" varchar(150) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_access_role_code" UNIQUE ("code")
);

CREATE TABLE "permission" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(80) NOT NULL,
  "resource_name" varchar(80) NOT NULL,
  "action_name" varchar(80) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_permission_code" UNIQUE ("code")
);

CREATE TABLE "user_role" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "app_user_id" bigint NOT NULL,
  "access_role_id" bigint NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_user_role_app_user_id_access_role_id" UNIQUE ("app_user_id", "access_role_id")
);

CREATE TABLE "role_permission" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "access_role_id" bigint NOT NULL,
  "permission_id" bigint NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_role_permission_access_role_id_permission_id" UNIQUE ("access_role_id", "permission_id")
);

CREATE TABLE "consent_record" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "app_user_id" bigint NOT NULL,
  "purpose_reference_value_id" bigint NOT NULL,
  "policy_version" varchar(80) NOT NULL,
  "granted_at" timestamptz NOT NULL,
  "revoked_at" timestamptz,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint
);

CREATE TABLE "blocking_entry" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "blocker_app_user_id" bigint NOT NULL,
  "blocked_app_user_id" bigint,
  "blocked_organisation_id" bigint,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "ck_blocking_entry_1" CHECK ((blocked_app_user_id IS NOT NULL) <> (blocked_organisation_id IS NOT NULL))
);

CREATE TABLE "audit_event" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "actor_app_user_id" bigint,
  "action_code" varchar(80) NOT NULL,
  "subject_token" varchar(255) NOT NULL,
  "outcome_reference_value_id" bigint NOT NULL,
  "correlation_key" varchar(80) NOT NULL,
  "occurred_at" timestamptz NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint
);

CREATE TABLE "system_error" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "error_code" varchar(80) NOT NULL,
  "correlation_key" varchar(80) NOT NULL,
  "sanitized_message" varchar(2000) NOT NULL,
  "occurred_at" timestamptz NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint
);

CREATE TABLE "integration_event" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "provider_code" varchar(80) NOT NULL,
  "provider_event_key" varchar(80) NOT NULL,
  "payload_hash" varchar(255) NOT NULL,
  "status_reference_value_id" bigint NOT NULL,
  "received_at" timestamptz NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  CONSTRAINT "uq_integration_event_provider_code_provider_event_key" UNIQUE ("provider_code", "provider_event_key")
);

CREATE TABLE "account" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "name" varchar(150) NOT NULL,
  "status_reference_value_id" bigint NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz
);

CREATE TABLE "organisation" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "account_id" bigint NOT NULL,
  "parent_organisation_id" bigint,
  "name" varchar(150) NOT NULL,
  "industry_id" bigint,
  "status_reference_value_id" bigint NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "ck_organisation_1" CHECK (parent_organisation_id IS NULL OR parent_organisation_id <> id)
);

CREATE TABLE "organisation_location" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "organisation_id" bigint NOT NULL,
  "city_id" bigint NOT NULL,
  "address_text" varchar(2000) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz
);

CREATE TABLE "organisation_identifier" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "organisation_id" bigint NOT NULL,
  "country_id" bigint NOT NULL,
  "type_reference_value_id" bigint NOT NULL,
  "identifier_token" varchar(255) NOT NULL,
  "masked_identifier" varchar(80) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz
);

CREATE TABLE "verification_record" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "organisation_id" bigint NOT NULL,
  "provider_token" varchar(255) NOT NULL,
  "outcome_reference_value_id" bigint NOT NULL,
  "verified_at" timestamptz,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz
);

CREATE TABLE "recruiter_membership" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "organisation_id" bigint NOT NULL,
  "app_user_id" bigint NOT NULL,
  "valid_from" timestamptz NOT NULL,
  "valid_to" timestamptz,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "ck_recruiter_membership_1" CHECK ("valid_to" IS NULL OR "valid_to" >= "valid_from")
);

CREATE TABLE "account_administrator" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "account_id" bigint NOT NULL,
  "app_user_id" bigint NOT NULL,
  "valid_from" timestamptz NOT NULL,
  "valid_to" timestamptz,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "ck_account_administrator_1" CHECK ("valid_to" IS NULL OR "valid_to" >= "valid_from")
);

CREATE TABLE "candidate_profile" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "app_user_id" bigint NOT NULL,
  "city_id" bigint,
  "headline" varchar(2000),
  "birth_date" date,
  "status_reference_value_id" bigint NOT NULL,
  "content_language" varchar(10) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_candidate_profile_app_user_id" UNIQUE ("app_user_id")
);

CREATE TABLE "candidate_contact" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "candidate_profile_id" bigint NOT NULL,
  "phone_number" varchar(16),
  "country_id" bigint,
  "contact_email" varchar(254),
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz
);

CREATE TABLE "candidate_education" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "candidate_profile_id" bigint NOT NULL,
  "qualification_id" bigint NOT NULL,
  "institution_name" varchar(150) NOT NULL,
  "start_date" date NOT NULL,
  "end_date" date,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "ck_candidate_education_1" CHECK ("end_date" IS NULL OR "end_date" >= "start_date")
);

CREATE TABLE "candidate_experience" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "candidate_profile_id" bigint NOT NULL,
  "employer_name" varchar(150) NOT NULL,
  "role_name" varchar(150) NOT NULL,
  "start_date" date NOT NULL,
  "end_date" date,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "ck_candidate_experience_1" CHECK ("end_date" IS NULL OR "end_date" >= "start_date")
);

CREATE TABLE "candidate_skill" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "candidate_profile_id" bigint NOT NULL,
  "skill_id" bigint NOT NULL,
  "proficiency_reference_value_id" bigint NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_candidate_skill_candidate_profile_id_skill_id" UNIQUE ("candidate_profile_id", "skill_id")
);

CREATE TABLE "candidate_language" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "candidate_profile_id" bigint NOT NULL,
  "language_code" varchar(10) NOT NULL,
  "proficiency_reference_value_id" bigint NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_candidate_language_candidate_profile_id_language_code" UNIQUE ("candidate_profile_id", "language_code")
);

CREATE TABLE "resume_template" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(80) NOT NULL,
  "name" varchar(150) NOT NULL,
  "template_object_key" varchar(512) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_resume_template_code" UNIQUE ("code")
);

CREATE TABLE "resume_version" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "candidate_profile_id" bigint NOT NULL,
  "resume_template_id" bigint,
  "version_number" integer NOT NULL,
  "object_key" varchar(512) NOT NULL,
  "content_hash" varchar(255) NOT NULL,
  "content_language" varchar(10) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_resume_version_candidate_profile_id_version_number" UNIQUE ("candidate_profile_id", "version_number"),
  CONSTRAINT "ck_resume_version_1" CHECK ("version_number" >= 0)
);

CREATE TABLE "candidate_project" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "candidate_profile_id" bigint NOT NULL,
  "title" varchar(150) NOT NULL,
  "role_name" varchar(150) NOT NULL,
  "start_date" date NOT NULL,
  "end_date" date,
  "outcome" varchar(2000),
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "ck_candidate_project_1" CHECK ("end_date" IS NULL OR "end_date" >= "start_date")
);

CREATE TABLE "assessment" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(80) NOT NULL,
  "name" varchar(150) NOT NULL,
  "maximum_score" numeric(12,4) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_assessment_code" UNIQUE ("code")
);

CREATE TABLE "assessment_attempt" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "candidate_profile_id" bigint NOT NULL,
  "assessment_id" bigint NOT NULL,
  "score" numeric(12,4) NOT NULL,
  "completed_at" timestamptz,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz
);

CREATE TABLE "course" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" varchar(80) NOT NULL,
  "name" varchar(150) NOT NULL,
  "provider_name" varchar(150) NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_course_code" UNIQUE ("code")
);

CREATE TABLE "course_enrolment" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "candidate_profile_id" bigint NOT NULL,
  "course_id" bigint NOT NULL,
  "status_reference_value_id" bigint NOT NULL,
  "enrolled_at" timestamptz NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  "deleted_at" timestamptz,
  CONSTRAINT "uq_course_enrolment_candidate_profile_id_course_id" UNIQUE ("candidate_profile_id", "course_id")
);

CREATE TABLE "profile_completion" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "candidate_profile_id" bigint NOT NULL,
  "rule_version" varchar(80) NOT NULL,
  "completion_percentage" numeric(5,2) NOT NULL,
  "calculated_at" timestamptz NOT NULL,
